mapper.insert:
insert into CREDIT_ASSETPOOL_DETAIL ( SEQNO, FINPROD_ID, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME ) select t1.seqno, t1.finprodId, t1.createUser, t1.createDept, t1.createTime, t1.updateUser, t1.updateTime from (
select #{item.seqno, jdbcType=VARCHAR} seqno, #{item.finprodId, jdbcType=VARCHAR} finprodId, #{item.createUser, jdbcType=VARCHAR} createUser, #{item.createDept, jdbcType=VARCHAR} createDept, #{item.createTime, jdbcType=TIMESTAMP} createTime, #{item.updateUser, jdbcType=VARCHAR} updateUser, #{item.updateTime, jdbcType=TIMESTAMP} updateTime from DUAL
)t1

mapper.delete:
delete from CREDIT_ASSETPOOL_DETAIL 
where 
	 SEQNO = #{seqno}
and  FINPROD_ID = #{finprodId}

mapper.select:
select count(1) cnt from
(  select 1  
	from CREDIT_ASSETPOOL
where ASSETPOOL_NAME = #{assetpoolName}

	 and  SEQNO <> #{seqno}


union all 
SELECT 1 FROM SYS_DATA_PROCESS_MARK 
  WHERE status IN ('A','N','M','U')

  		and page_id = #{pageId}  


	and  business_data_pk1 <> #{seqno}

AND business_data_pk2 = #{assetpoolName}
)

select count(1)
	from CREDIT_ASSETPOOL_DETAIL
where FINPROD_ID = #{finprodId}

select ASSETPOOL_NAME from ( SELECT ASSETPOOL_NAME, INSTITUTION_CODE FROM CREDIT_ASSETPOOL WHERE SEQNO IN (SELECT SEQNO FROM CREDIT_ASSETPOOL_DETAIL WHERE FINPROD_ID = #{finprodId} ) AND ASSETPOOL_NAME IS NOT NULL AND ROWNUM = 1
and INSTITUTION_CODE in #{institutionCode}
)

select count(1)
	from CREDIT_LINES
where CREDIT_MST_ID = '0002'
and CUSTOMER_ID = #{finprodId}

    and INSTITUTION_CODE = #{institutionCode}

select count(1)
	from CREDIT_ASSETPOOL_DETAIL
where SEQNO = #{seqno}

